@push('scripts')<script>document.addEventListener('DOMContentLoaded',function(){const form=document.querySelector('form[action*="return-request"]'),reason=document.getElementById('returnReason'),wrap=document.getElementById('otherReasonWrap'),other=document.getElementById('otherReason'),photos=document.querySelector('input[name="photos[]"]'),videoInput=document.querySelector('input[name="video"]');const sync=()=>{const show=reason?.value==='other';wrap.hidden=!show;other.required=show;if(show)other.focus();};const validatePhotos=()=>{const count=photos?.files?.length??0;photos?.setCustomValidity(count>=2?'':'Please upload at least 2 photos as evidence.');};reason?.addEventListener('change',sync);photos?.addEventListener('change',validatePhotos);form?.addEventListener('submit',validatePhotos,true);sync();validatePhotos();videoInput?.addEventListener('change',function(){const file=this.files?.[0];if(!file)return;const video=document.createElement('video');video.preload='metadata';video.onloadedmetadata=()=>{URL.revokeObjectURL(video.src);if(video.duration>60){this.value='';this.setCustomValidity('Please upload a video that is 60 seconds or shorter.');this.reportValidity();}else this.setCustomValidity('');};video.src=URL.createObjectURL(file);});});</script>@endpush
